/*
 * ==========================================================================
 * UVa 694 - The Collatz Sequence
 * Title-CN: 考拉茲序列帶上限步數計算
 * Difficulty: UVa Star 1
 * Tags: simulation, math
 * URL: https://onlinejudge.org/external/6/694.pdf
 * ==========================================================================
 * [EN] Problem:
 *     Compute number of terms in Collatz sequence generated by A until term becomes 1 or exceeds limit L.
 *
 * [中文] 題目說明:
 *     計算起始值為 A 的 3n+1 序列項數，直到數值抵達 1 或運算中途數值超出上限 L 為止。
 *
 * [EN] Approach:
 *     Step-by-step simulation using 64-bit integer. Stop when term == 1 or term > L.
 * [中文] 思路:
 *     以 64 位元整數模擬 3n+1 運算流程，當前項超過限制 L 或抵達 1 時終止並統計有效項數。
 * ==========================================================================
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

long long solve_uva694(long long a, long long limit) {
    long long terms = 0;
    while (a <= limit) {
        terms++;
        if (a == 1) break;
        if (a % 2 == 1) a = 3 * a + 1;
        else a /= 2;
    }
    return terms;
}

int main(void) {

    int ok = (solve_uva694(3, 100) == 8);
    printf("%s: UVa 694 - The Collatz Sequence\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}
